const fs = require('fs');
const { execFile } = require('child_process');
const data = JSON.parse(fs.readFileSync('/usr/share/iso-codes/json/iso_4217.json', 'utf8'))['4217'];
const codes = data.map((entry) => entry.alpha_3);
const execPath = '/workspace/dataset/test10_executable';
const concurrency = 8;
let index = 0;
const results = [];
function runOne(code) {
  return new Promise((resolve) => {
    execFile(execPath, ['--amount', '1', '--currency', code], { encoding: 'buffer' }, (error, stdout, stderr) => {
      if (error) {
        resolve({ code, ok: false, status: error.code, stderr: String(stderr) });
        return;
      }
      const text = Buffer.from(stdout).toString('utf8').replace(/\n$/, '');
      const m = text.match(/^(.*)\u00a0([0-9]+(?:\.([0-9]+))?)$/u);
      if (!m) {
        resolve({ code, ok: true, text, parse: null });
        return;
      }
      resolve({ code, ok: true, prefix: m[1], decimals: m[3] ? m[3].length : 0, text });
    });
  });
}
async function worker() {
  while (index < codes.length) {
    const code = codes[index++];
    results.push(await runOne(code));
  }
}
(async () => {
  await Promise.all(Array.from({ length: concurrency }, worker));
  results.sort((a, b) => a.code.localeCompare(b.code));
