import { looksLikeArgparseNegativeNumber, parsePythonFloatToken } from './number-format.mjs';

const LONG_OPTIONS = ['--help', '--amount', '--currency'];

export class ParserExit extends Error {
  constructor(status, stream, text) {
    super(text);
    this.name = 'ParserExit';
    this.status = status;
    this.stream = stream;
    this.text = text;
  }
}

export function parseArgs(argv, programName) {
  let amount;
  let currency;
  let hasAmount = false;
  let hasCurrency = false;
  let endOfOptions = false;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (endOfOptions) {
      extras.push(token);
      continue;
    }

    if (token === '--') {
      endOfOptions = true;
      continue;
    }

    if (token === '-h') {
      throw new ParserExit(0, 'stdout', buildHelpText(programName));
    }

    if (!token.startsWith('--') && token.startsWith('-h')) {
      fail(programName, `argument -h/--help: ignored explicit argument '${token.slice(2).replace(/^=/, '')}'`);
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const optionToken = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const attachedValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);
      const option = resolveLongOption(optionToken);

      if (option == null) {
        extras.push(token);
        continue;
      }

      if (option === '--help') {
        if (attachedValue != null) {
          fail(programName, `argument -h/--help: ignored explicit argument '${attachedValue}'`);
        }
        throw new ParserExit(0, 'stdout', buildHelpText(programName));
      }

      const valueState =
        attachedValue != null
          ? { value: attachedValue, nextIndex: index }
          : consumeOptionValue(argv, index, option, programName);
      index = valueState.nextIndex;

      if (option === '--amount') {
        const parsed = parsePythonFloatToken(valueState.value);
        if (!parsed.ok) {
          fail(programName, `argument --amount: invalid float value: '${valueState.value}'`);
        }
        amount = parsed.value;
        hasAmount = true;
        continue;
      }

      currency = valueState.value;
      hasCurrency = true;
      continue;
    }

    extras.push(token);
  }

  const missing = [];
  if (!hasAmount) {
    missing.push('--amount');
  }
  if (!hasCurrency) {
    missing.push('--currency');
  }

  if (missing.length > 0) {
    fail(programName, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    fail(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { amount, currency };
}

function buildUsage(programName) {
  return `usage: ${programName} [-h] --amount AMOUNT --currency CURRENCY`;
}

function buildHelpText(programName) {
  return `${buildUsage(programName)}\n\noptions:\n  -h, --help           show this help message and exit\n  --amount AMOUNT\n  --currency CURRENCY\n`;
}

function fail(programName, message) {
  throw new ParserExit(2, 'stderr', `${buildUsage(programName)}\n${programName}: error: ${message}\n`);
}

function resolveLongOption(optionToken) {
  const matches = LONG_OPTIONS.filter((candidate) => candidate.startsWith(optionToken));
  return matches.length === 1 ? matches[0] : null;
}

function consumeOptionValue(argv, index, option, programName) {
  const value = argv[index + 1];

  if (value == null) {
    fail(programName, `argument ${option}: expected one argument`);
  }

  if (value.startsWith('-')) {
    const acceptsNegativeNumber = option === '--amount' && looksLikeArgparseNegativeNumber(value);
    if (!acceptsNegativeNumber) {
      fail(programName, `argument ${option}: expected one argument`);
    }
  }

  return { value, nextIndex: index + 1 };
}

