import { CURRENCY_OVERRIDES, DEFAULT_DECIMALS, VALID_CURRENCY_CODES } from './currency-data.mjs';
import { formatNumericAmount } from './number-format.mjs';

const NBSP = '\u00A0';

export class CurrencyDoesNotExist extends Error {
  constructor(code) {
    super(`No currency with code ${code} is defined.`);
    this.name = 'CurrencyDoesNotExist';
  }
}

export class Money {
  constructor(amount, currencyCode) {
    this.amount = amount;
    this.currency = getCurrencyFormat(currencyCode);
  }

  toString() {
    const negative = !Number.isNaN(this.amount) && (this.amount < 0 || Object.is(this.amount, -0));
    const prefix = `${negative ? '-' : ''}${this.currency.prefix}${NBSP}`;
    return `${prefix}${formatNumericAmount(this.amount, this.currency.decimals)}`;
  }
}

export function getCurrencyFormat(currencyCode) {
  const normalizedCode = String(currencyCode).toUpperCase();
  if (!VALID_CURRENCY_CODES.has(normalizedCode)) {
    throw new CurrencyDoesNotExist(normalizedCode);
  }

  const override = CURRENCY_OVERRIDES[normalizedCode] ?? {};
  return {
    code: normalizedCode,
    prefix: override.prefix ?? normalizedCode,
    decimals: override.decimals ?? DEFAULT_DECIMALS,
  };
}

export function formatMoney(amount, currencyCode) {
  return new Money(amount, currencyCode).toString();
}

