const FLOAT_TOKEN_RE =
  /^[+-]?(?:(?:\d(?:_?\d)*\.\d(?:_?\d)*|\d(?:_?\d)*\.|\.\d(?:_?\d)*|\d(?:_?\d)*)(?:[eE][+-]?\d(?:_?\d)*)?|inf(?:inity)?|nan)$/i;

const NEGATIVE_NUMBER_TOKEN_RE = /^-(?:\d+|\d*\.\d+)$/;

export function looksLikeArgparseNegativeNumber(token) {
  return NEGATIVE_NUMBER_TOKEN_RE.test(token);
}

export function parsePythonFloatToken(token) {
  if (!FLOAT_TOKEN_RE.test(token)) {
    return { ok: false };
  }

  const normalized = token.replace(/_/g, '');

  if (/^[+-]?nan$/i.test(normalized)) {
    return { ok: true, value: Number.NaN };
  }

  if (/^[+-]?inf(?:inity)?$/i.test(normalized)) {
    return {
      ok: true,
      value: normalized.startsWith('-') ? Number.NEGATIVE_INFINITY : Number.POSITIVE_INFINITY,
    };
  }

  const value = Number(normalized);
  if (Number.isNaN(value)) {
    return { ok: false };
  }

  return { ok: true, value };
}

export function formatNumericAmount(value, decimals) {
  if (Number.isNaN(value)) {
    return decimals === 0 ? 'NaN' : `NaN.${'0'.repeat(decimals)}`;
  }

  if (!Number.isFinite(value)) {
    return 'INF';
  }

  return roundHalfEven(toPlainDecimalString(Math.abs(value)), decimals);
}

export function toPlainDecimalString(value) {
  const text = String(value);
  if (!/[eE]/.test(text)) {
    return text;
  }

  const match = text.match(/^(\d+)(?:\.(\d+))?[eE]([+-]?\d+)$/);
  if (!match) {
    return text;
  }

  const integerPart = match[1];
  const fractionalPart = match[2] ?? '';
  const exponent = Number(match[3]);
  const digits = integerPart + fractionalPart;
  const decimalIndex = integerPart.length + exponent;

  if (decimalIndex <= 0) {
    return `0.${'0'.repeat(-decimalIndex)}${digits}`;
  }

  if (decimalIndex >= digits.length) {
    return `${digits}${'0'.repeat(decimalIndex - digits.length)}`;
  }

  return `${digits.slice(0, decimalIndex)}.${digits.slice(decimalIndex)}`;
}

export function roundHalfEven(decimalText, decimals) {
  let [integerPart, fractionalPart = ''] = decimalText.split('.');
  integerPart = integerPart || '0';

  if (fractionalPart.length < decimals) {
    fractionalPart = fractionalPart.padEnd(decimals, '0');
    return decimals === 0 ? integerPart : `${integerPart}.${fractionalPart}`;
  }

  const keptFraction = fractionalPart.slice(0, decimals);
  const nextDigit = fractionalPart[decimals];

  if (!nextDigit) {
    return decimals === 0 ? integerPart : `${integerPart}.${keptFraction}`;
  }

  const roundedUp = shouldRoundUp(integerPart, keptFraction, nextDigit, fractionalPart.slice(decimals + 1));
  let combined = integerPart + keptFraction.padEnd(decimals, '0');

  if (roundedUp) {
    combined = incrementDigits(combined);
  }

  if (decimals === 0) {
    return combined;
  }

  combined = combined.padStart(decimals + 1, '0');
  const cut = combined.length - decimals;
  return `${combined.slice(0, cut)}.${combined.slice(cut)}`;
}

function shouldRoundUp(integerPart, keptFraction, nextDigit, remainder) {
  if (nextDigit < '5') {
    return false;
  }

  if (nextDigit > '5') {
    return true;
  }

  if (/[1-9]/.test(remainder)) {
    return true;
  }

  const anchor = keptFraction ? keptFraction[keptFraction.length - 1] : integerPart[integerPart.length - 1] ?? '0';
  return Number(anchor) % 2 === 1;
}

function incrementDigits(digits) {
  const result = digits.split('');
  let carry = 1;

  for (let index = result.length - 1; index >= 0 && carry === 1; index -= 1) {
    const nextDigit = result[index].charCodeAt(0) - 48 + carry;
    result[index] = String(nextDigit % 10);
    carry = nextDigit >= 10 ? 1 : 0;
  }

  if (carry === 1) {
    result.unshift('1');
  }

  return result.join('');
}

